package toolshed;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Test-only: a second controller whose lookup always fails. The checks call
 * it to see that ToolNotFoundException is handled globally, in ApiErrors,
 * whichever controller it comes from. Do not edit this file.
 */
@RestController
class MissingToolProbe {

    static final String PATH = "/test-only/missing-tool";

    @GetMapping(PATH)
    String missingTool() {
        throw new ToolNotFoundException(55);
    }
}
